local _payload = ''

local function _decode(b64)
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    b64 = string.gsub(b64, '[^'..b..'=]', '')
    return (b64:gsub('.', function(x)
        if (x == '=') then return '' end
        local r, f = '', (b:find(x) - 1)
        for i = 6, 1, -1 do r = r .. (f % 2^i >= 2^(i - 1) and '1' or '0') end
        return r
    end):gsub('%d%d%d%d%d%d%d%d', function(x)
        local c = 0
        for i = 1, 8 do if (x:sub(i, i) == '1') then c = c + 2^(8 - i) end end
        return string.char(c)
    end))
end

local _src = _decode(_payload)
local _fn, _err = loadstring(_src)
if _fn then
    _fn()
else
    error('Failed to run obfuscated script: ' .. tostring(_err))
end
